package com.triathlon.prep.core;
import java.io.*;import java.util.*;
/** Worker-owned, explicit current-roster selection/commit. No automatic comparison or first-row inference. */
public final class ManualPassportCheck {
 public enum State { READY,SEARCHING,SELECTED,SAVING,CONFIRMED,PRINTING,FAILED,NO_ROSTER }
 public static final class Candidate {public final String token,bib,name,group,team;private Candidate(String token,RaceRoster.Athlete a){this.token=token;bib=a.bib;name=a.name;group=a.group;team=a.team;}}
 public static final class Selection {public final String token,batchId,bib,name,group,team,documentNumber,recordId;public final DocumentNumber.Type documentType;public final RaceRoster.SwimTest swimTest;public final boolean completed;private Selection(String token,RaceRoster roster,RaceRoster.Entry e,ManualRecord record){this.token=token;batchId=roster.batchId;RaceRoster.Athlete a=e.athlete;bib=a.bib;name=a.name;group=a.group;team=a.team;documentNumber=e.originalDocument();documentType=e.documentType();swimTest=a.swimTest;completed=record!=null;recordId=record==null?"":record.id;}}
 public static final class Snapshot {public final String query,queryToken,notice;public final State state;public final List<Candidate> matches;public final Selection selected;public final int page,pageCount,totalMatches;public final ManualRecord record;public final boolean newConfirmation;public final CheckIn.State checkIn;private Snapshot(ManualPassportCheck c){query=c.query;queryToken=c.queryToken;notice=c.notice;state=c.state;matches=Collections.unmodifiableList(new ArrayList<>(c.matches));selected=c.selection;page=c.page;totalMatches=c.total;pageCount=(c.total+49)/50;record=c.record;newConfirmation=c.newConfirmation;checkIn=c.checkIn;}}
 private final Verification.Mode mode;private final Verification.RosterProvider rosters;private final ManualRecordStore store;private final Verification.Clock clock;
 private String query="",queryToken=UUID.randomUUID().toString(),notice="输入姓名、比赛号码或护照号码，明确选择后核对护照与本人。";private State state=State.READY;private List<Candidate> matches=new ArrayList<>();private final Map<String,RaceRoster.Entry> candidates=new HashMap<>();private RaceRoster pinned;private RaceRoster.Entry entry;private Selection selection;private ManualRecord record;private int page,total;private boolean newConfirmation;private CheckIn.State checkIn=CheckIn.State.NOT_SUCCESS;
 public ManualPassportCheck(Verification.Mode mode,Verification.RosterProvider rosters,ManualRecordStore store,Verification.Clock clock){if(mode==null||rosters==null||store==null||clock==null)throw new IllegalArgumentException("Manual channel dependencies required");this.mode=mode;this.rosters=rosters;this.store=store;this.clock=clock;}
 public synchronized Snapshot snapshot(){return new Snapshot(this);}
 public synchronized Snapshot presentation(State state,String notice){State previous=this.state;String old=this.notice;this.state=state;this.notice=notice;Snapshot result=snapshot();this.state=previous;this.notice=old;return result;}
 private void clear(){entry=null;selection=null;record=null;newConfirmation=false;checkIn=CheckIn.State.NOT_SUCCESS;queryToken=UUID.randomUUID().toString();matches.clear();candidates.clear();total=0;page=0;}
 private Snapshot fail(String message){clear();state=State.FAILED;notice=message;return snapshot();}
 public synchronized Snapshot search(String text,int requestedPage){clear();query=text==null?"":text.trim();try{pinned=rosters.current();if(pinned==null){state=State.NO_ROSTER;notice="没有有效名单，不能人工核验或打印。";return snapshot();}if(query.isEmpty()){state=State.READY;notice="请输入查询条件，不会默认选中任何人。";return snapshot();}if(query.length()>128)return fail("查询过长，请缩短。" );String needle=query.toUpperCase(Locale.ROOT);List<RaceRoster.Entry> found=new ArrayList<>();for(RaceRoster.Entry e:pinned.storedEntries()){RaceRoster.Athlete a=e.athlete;if(a.name.toUpperCase(Locale.ROOT).contains(needle)||a.bib.toUpperCase(Locale.ROOT).contains(needle)||e.identity().contains(needle))found.add(e);}total=found.size();page=Math.max(0,Math.min(requestedPage,Math.max(0,(total-1)/50)));for(int i=page*50;i<Math.min(total,(page+1)*50);i++){String token=UUID.randomUUID().toString();RaceRoster.Entry e=found.get(i);candidates.put(token,e);matches.add(new Candidate(token,e.athlete));}state=State.READY;notice=total==0?"没有匹配名单人员，不能打印。":"找到"+total+"人，请明确选择并核对；不会默认取首条。";return snapshot();}catch(IOException|RuntimeException e){return fail("名单读取失败，未形成有效人工选择。" );}}
 private boolean sameEntry(RaceRoster.Entry a,RaceRoster.Entry b){return a.key().equals(b.key())&&a.originalDocument().equals(b.originalDocument())&&a.athlete.bib.equals(b.athlete.bib)&&a.athlete.name.equals(b.athlete.name)&&a.athlete.group.equals(b.athlete.group)&&a.athlete.team.equals(b.athlete.team)&&a.athlete.swimTest==b.athlete.swimTest;}
 private boolean currentEntry()throws IOException{if(pinned==null||entry==null||selection==null)return false;RaceRoster now=rosters.current();if(now==null||!now.batchId.equals(pinned.batchId))return false;RaceRoster.Entry current=now.entryByBib(entry.athlete.bib);return current!=null&&sameEntry(entry,current);}
 private ManualRecord completed()throws IOException{if(entry==null||pinned==null)return null;return store.find(mode,pinned.batchId,entry.athlete.bib);}
 public synchronized Snapshot select(String token){RaceRoster.Entry e=candidates.get(token);if(e==null)return fail("旧候选已失效，请重新搜索选择。" );entry=e;selection=new Selection(UUID.randomUUID().toString(),pinned,e,null);try{if(!currentEntry())return fail("名单已变化，请重新搜索选择。" );record=completed();selection=new Selection(selection.token,pinned,e,record);state=record==null?State.SELECTED:State.CONFIRMED;newConfirmation=false;checkIn=record==null?CheckIn.State.NOT_SUCCESS:CheckIn.State.DUPLICATE;notice=record==null?"请核对护照原件与本人，再明确确认人工核验。":"该选手已报到，请勿重复办理；补打须明确确认。";return snapshot();}catch(IOException|RuntimeException error){return fail("人工历史读取失败，未产生核验或打印。" );}}
 public synchronized Snapshot confirm(String token){try{if(selection==null||!selection.token.equals(token)||!currentEntry())return fail("旧选择已失效，未保存或打印。" );ManualRecord existing=completed();if(existing!=null){record=existing;selection=new Selection(selection.token,pinned,entry,record);newConfirmation=false;checkIn=CheckIn.State.DUPLICATE;state=State.CONFIRMED;notice="该选手已报到，请勿重复办理；补打须明确确认。";return snapshot();}state=State.SAVING;ManualRecord proposed=new ManualRecord(UUID.randomUUID().toString(),clock.wallMillis(),mode,pinned.batchId,entry.athlete.bib);ManualRecordStore.Commit committed=store.commitCheckIn(proposed);record=committed.record;checkIn=committed.checkIn;newConfirmation=checkIn==CheckIn.State.FIRST&&record.id.equals(proposed.id);selection=new Selection(selection.token,pinned,entry,record);state=State.CONFIRMED;notice=checkIn==CheckIn.State.DUPLICATE?"该选手已报到，请勿重复办理。本次未自动打印。":checkIn==CheckIn.State.UNLINKABLE?"历史报到记录待核对；本次未自动打印。":"MANUAL · 人工已通过并保存；未代表自动人脸通过。";return snapshot();}catch(IOException|RuntimeException error){newConfirmation=false;record=null;state=State.FAILED;notice="人工核验未保存，不会打印；可核对后重试。";return snapshot();}}
 public synchronized ManualPrintAuthorization authorizeInitialPrint(String token){if(!newConfirmation)return null;ManualPrintAuthorization auth=authorize(token,false);if(auth!=null)newConfirmation=false;return auth;}
 public synchronized ManualPrintAuthorization authorizeReprint(String token){return authorize(token,true);}
 private ManualPrintAuthorization authorize(String token,boolean reprint){try{if(selection==null||!selection.token.equals(token)||!currentEntry())return null;ManualRecord saved=completed();if(saved==null)return null;record=saved;return new ManualPrintAuthorization(this,token,saved,pinned.eventName,entry.athlete,reprint);}catch(IOException|RuntimeException error){return null;}}
 synchronized boolean authorizationCurrent(String token,ManualRecord record){try{if(selection==null||!selection.token.equals(token)||!currentEntry())return false;ManualRecord stored=completed();return stored!=null&&stored.id.equals(record.id)&&stored.mode==record.mode&&stored.timestamp==record.timestamp;}catch(IOException|RuntimeException error){return false;}}
 public synchronized void invalidate(){clear();pinned=null;state=State.READY;notice="请重新搜索选择。";}
 public void close(){invalidate();}
}

